"""
PC Agent Voice Command Registry — 7,000+ Commands Across 95 Categories.

This module is the single source of truth for all PC voice commands.
It provides:
  1. COMMAND_CATEGORIES — metadata for all 95 categories
  2. FAST_PATTERNS — regex patterns for the CommandRouter fast-path
  3. KEYWORD_ROUTES — keyword groups used by IntentParser nuclear options
  4. APP_REGISTRY — comprehensive app name → executable mapping
  5. WEBSITE_REGISTRY — site name → URL mapping
  6. SYSTEM_COMMANDS — direct action mappings for system-level commands
"""

import re
from typing import Dict, List, Any, Optional, Tuple

