# ═══════════════════════════════════════════════════════════════════════
# 7. HELPER FUNCTIONS
# ═══════════════════════════════════════════════════════════════════════

def extract_volume_level(text: str) -> Optional[int]:
    """Extract a volume percentage from text like 'set volume to 50%'."""
    match = re.search(r"(?:set\s+)?volume\s+(?:to\s+)?(\d+)\s*%?", text, re.IGNORECASE)
    if match:
        return min(100, max(0, int(match.group(1))))
    return None


def extract_brightness_level(text: str) -> Optional[int]:
    """Extract a brightness percentage from text like 'set brightness to 80%'."""
    match = re.search(r"(?:set\s+)?brightness\s+(?:to\s+)?(\d+)\s*%?", text, re.IGNORECASE)
    if match:
        return min(100, max(0, int(match.group(1))))
    return None


def extract_timer_minutes(text: str) -> Optional[int]:
    """Extract minutes from shutdown timer like 'shut down in 30 minutes'."""
    match = re.search(r"(?:shut\s*down|power\s+off)\s+in\s+(\d+)\s+(?:min|minute)", text, re.IGNORECASE)
    if match:
        return int(match.group(1))
    return None


def extract_resolution(text: str) -> Optional[str]:
    """Extract resolution from text like 'change resolution to 1920x1080'."""
    match = re.search(r"(\d{3,4})\s*[xX×]\s*(\d{3,4})", text)
    if match:
        return f"{match.group(1)}x{match.group(2)}"
    # Named resolutions
    named = {"4k": "3840x2160", "1440p": "2560x1440", "1080p": "1920x1080",
             "720p": "1280x720", "2k": "2560x1440"}
    for name, res in named.items():
        if name in text.lower():
            return res
    return None


def extract_virtual_desktop_number(text: str) -> Optional[int]:
    """Extract virtual desktop number from text like 'switch to desktop 2'."""
    match = re.search(r"(?:desktop|space)\s+(\d+)", text, re.IGNORECASE)
    if match:
        return int(match.group(1))
    return None


def extract_process_name(text: str) -> Optional[str]:
    """Extract process name from text like 'kill process chrome'."""
    match = re.search(r"(?:kill\s+process|end\s+task)\s+(.+)", text, re.IGNORECASE)
    if match:
        return match.group(1).strip()
    return None


def extract_settings_page(text: str) -> Optional[str]:
    """Extract the settings page from text like 'open display settings'."""
    settings_map = {
        "display": "display",
        "sound": "sound",
        "audio": "sound",
        "notification": "notifications",
        "privacy": "privacy",
        "security": "privacy",
        "update": "windowsupdate",
        "storage": "storagesense",
        "power": "powersleep",
        "battery": "batterysaver",
        "network": "network-status",
        "wifi": "network-wifi",
        "bluetooth": "bluetooth",
        "mouse": "mousetouchpad",
        "touchpad": "mousetouchpad",
        "keyboard": "typing",
        "printer": "printers",
        "app": "appsfeatures",
        "default app": "defaultapps",
        "startup": "startupapps",
        "personalization": "personalization",
        "wallpaper": "personalization-background",
        "theme": "themes",
        "color": "colors",
        "lock screen": "lockscreen",
        "font": "fonts",
        "region": "regionlanguage",
        "language": "regionlanguage",
        "time": "dateandtime",
        "date": "dateandtime",
        "about": "about",
        "system": "about",
    }
    text_lower = text.lower()
    for keyword, page in settings_map.items():
        if keyword in text_lower:
            return page
    return "main"


def match_system_command(text: str) -> Optional[Dict[str, Any]]:
    """
    Try to match the input text against all known system command registries.
    Returns the matched command dict or None.
    """
    text_lower = text.lower().strip()

    # Check all command dictionaries in priority order
    all_commands = [
        SYSTEM_POWER_COMMANDS,
        VOLUME_COMMANDS,
        BRIGHTNESS_COMMANDS,
        DISPLAY_COMMANDS,
        WINDOW_COMMANDS,
        SCREENSHOT_COMMANDS,
        FILE_COMMANDS,
        SETTINGS_COMMANDS,
        NETWORK_COMMANDS,
        KEYBOARD_MOUSE_COMMANDS,
        CLIPBOARD_COMMANDS,
        DICTATION_COMMANDS,
        BROWSER_COMMANDS,
        EMAIL_COMMANDS,
        CALENDAR_COMMANDS,
        COMMUNICATION_COMMANDS,
        SECURITY_COMMANDS,
        PRINT_PDF_COMMANDS,
        OPTIMIZATION_COMMANDS,
        GAMING_COMMANDS,
        PERIPHERAL_COMMANDS,
        META_COMMANDS,
        WORD_PROCESSING_COMMANDS,
        SPREADSHEET_COMMANDS,
        PRESENTATION_COMMANDS,
        NOTES_COMMANDS,
        DESIGN_COMMANDS,
        CODING_COMMANDS,
        VIDEO_EDITING_COMMANDS,
        AUDIO_COMMANDS,
        DATA_ANALYTICS_COMMANDS,
        BUSINESS_COMMANDS,
        AI_ASSISTANT_COMMANDS,
        SOCIAL_MEDIA_COMMANDS,
        FILE_CONVERSION_COMMANDS,
        CHAINING_COMMANDS,
        FOCUS_COMMANDS,
        CONTENT_CREATION_COMMANDS,
        ECOMMERCE_COMMANDS,
        SEO_COMMANDS,
        CUSTOMER_SUPPORT_COMMANDS,
        COLLABORATION_COMMANDS,
        DOCUMENT_SIGNING_COMMANDS,
        SCHEDULING_COMMANDS,
        DIAGRAMMING_COMMANDS,
        RESEARCH_COMMANDS,
        CICD_COMMANDS,
        CLOUD_COMMANDS,
        TESTING_COMMANDS,
        AUTOMATION_COMMANDS,
        REMOTE_DESKTOP_COMMANDS,
        BACKUP_COMMANDS,
        VM_COMMANDS,
        STREAMING_COMMANDS,
        PASSWORD_COMMANDS,
        CLOUD_STORAGE_COMMANDS,
        EMAIL_MARKETING_COMMANDS,
        PAYMENT_COMMANDS,
        PROJECT_MANAGEMENT_COMMANDS,
        WEBSITE_BUILDER_COMMANDS,
        NOTIFICATION_COMMANDS,
        FONT_COMMANDS,
        WEBCAM_COMMANDS,
        LOCALIZATION_COMMANDS,
        SSH_COMMANDS,
        LINK_COMMANDS,
        CODE_REVIEW_COMMANDS,
        MAPPING_COMMANDS,
        DECLUTTER_COMMANDS,
        PERSONAL_FINANCE_COMMANDS,
        MONITORING_COMMANDS,
        ENTERPRISE_IT_COMMANDS,
        SPECIALIZED_SOFTWARE_COMMANDS,
        MOBILE_DEVICE_COMMANDS,
        DATABASE_COMMANDS,
        BATCH_COMMANDS,
        WORKFLOW_CHAIN_COMMANDS,
        ZAPIER_COMMANDS,
        MAKE_COMMANDS,
        N8N_COMMANDS,
        POWER_AUTOMATE_COMMANDS,
        AUTOHOTKEY_COMMANDS,
        API_COMMANDS,
        CRM_COMMANDS,
        ACCOUNTING_COMMANDS,
        HR_COMMANDS,
        CROSS_DEVICE_COMMANDS,
        LEARNING_COMMANDS,
        PACKAGE_COMMANDS,
        GIT_COMMANDS,
        DOCKER_COMMANDS,
        SNIPPET_COMMANDS,
        WINDOW_DEEP_COMMANDS,
        SEARCH_DEEP_COMMANDS,
        DICTATION_DEEP_COMMANDS,
        CONDITIONAL_COMMANDS,
        INTEGRATION_COMMANDS,
        ADS_COMMANDS,
        KNOWLEDGE_BASE_COMMANDS,
    ]

    for cmd_dict in all_commands:
        for pattern, cmd_info in cmd_dict.items():
            if text_lower == pattern or text_lower.startswith(pattern):
                return cmd_info

    # Check for parameterized commands
    vol_level = extract_volume_level(text_lower)
    if vol_level is not None:
        return {"action": "volume", "params": {"level": vol_level}}

    bright_level = extract_brightness_level(text_lower)
    if bright_level is not None:
        return {"action": "brightness", "params": {"level": bright_level}}

    timer = extract_timer_minutes(text_lower)
    if timer is not None:
        return {"action": "system_power", "params": {"operation": "shutdown", "delay_minutes": timer}}

    resolution = extract_resolution(text_lower)
    if resolution and "resolution" in text_lower:
        return {"action": "display", "params": {"resolution": resolution}}

    desktop_num = extract_virtual_desktop_number(text_lower)
    if desktop_num is not None and "desktop" in text_lower and "switch" in text_lower:
        return {"action": "window_management", "params": {"operation": "switch_virtual_desktop", "desktop_number": desktop_num}}

    return None


def match_app_name(text: str) -> Optional[str]:
    """Match an app name from the registry, returning the executable path."""
    text_lower = text.lower().strip()
    # Try exact match first
    if text_lower in APP_REGISTRY:
        return APP_REGISTRY[text_lower]
    # Try startswith match (for "open chrome browser" → "chrome")
    for app_name, app_path in sorted(APP_REGISTRY.items(), key=lambda x: -len(x[0])):
        if text_lower.startswith(app_name):
            return app_path
    return None


def match_website(text: str) -> Optional[str]:
    """Match a website name from the registry, returning the URL."""
    text_lower = text.lower().strip()
    if text_lower in WEBSITE_REGISTRY:
        return WEBSITE_REGISTRY[text_lower]
    # Try partial match
    for site_name, url in sorted(WEBSITE_REGISTRY.items(), key=lambda x: -len(x[0])):
        if text_lower.startswith(site_name):
            return url
    return None


def get_category_count() -> int:
    """Return the total number of command categories."""
    return len(COMMAND_CATEGORIES)


def get_all_app_names() -> List[str]:
    """Return all known app names."""
    return list(APP_REGISTRY.keys())


def get_all_website_names() -> List[str]:
    """Return all known website names."""
    return list(WEBSITE_REGISTRY.keys())
